<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake</title>
<style>
  body{margin:0;background:#0d0d0d;color:#eee;font-family:system-ui,sans-serif;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:100vh}
  #wrap{text-align:center}
  #snake{background:#111;border:2px solid #333;display:block;margin:0 auto}
  #controls{margin-top:12px}
  #controls button{margin:0 6px;padding:8px 14px;background:#222;color:#eee;border:1px solid #444;border-radius:6px;cursor:pointer}
  #controls button:hover{background:#333}
  #score{margin-top:12px;font-size:18px}
</style>
</head>
<body>
<div id="wrap">
  <canvas id="snake" width="400" height="400"></canvas>
  <div id="controls">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
  </div>
  <div id="score">Score: 0</div>
</div>
<script>
const canvas = document.getElementById('snake');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');

const w = 20, h = 20;
const cell = 400 / w;

let snake, dir, nextDir, food, alive, score;
let intervalId = null;

function randFood(){
  let x,y;
  do{
    x = Math.floor(Math.random()*w);
    y = Math.floor(Math.random()*h);
  }while(snake.some(p=>p.x===x && p.y===y));
  food = {x,y};
}

function reset(){
  alive = true;
  score = 0;
  dir = {x:1,y:0};
  nextDir = null;
  const cx = Math.floor(w/2), cy = Math.floor(h/2);
  snake = [];
  for(let i=0;i<4;i++) snake.push({x:cx - i, y:cy});
  randFood();
  updateScore();
  draw();
}

function draw(){
  ctx.fillStyle = '#111';
  ctx.fillRect(0,0,canvas.width,canvas.height);
  // food
  ctx.fillStyle = '#ff5252';
  ctx.beginPath();
  ctx.arc(food.x*cell + cell/2, food.y*cell + cell/2, cell*0.35, 0, Math.PI*2);
  ctx.fill();
  // snake
  snake.forEach((p,i)=>{
    ctx.fillStyle = i===0 ? '#7fff7f' : '#0f0';
    ctx.fillRect(p.x*cell+1, p.y*cell+1, cell-2, cell-2);
  });
  if(!alive){
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '28px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width/2, canvas.height/2);
  }
}

function updateScore(){
  scoreEl.textContent = 'Score: ' + score;
}

function tick(){
  if(!alive) return;
  if(nextDir){
    if(!(nextDir.x === -dir.x && nextDir.y === -dir.y)){
      dir = nextDir;
    }
    nextDir = null;
  }
  const head = snake[0];
  const nx = head.x + dir.x;
  const ny = head.y + dir.y;
  if(nx < 0 || nx >= w || ny < 0 || ny >= h){
    alive = false;
    stopLoop();
    draw();
    return;
  }
  const willEat = nx === food.x && ny === food.y;
  const bodyCheck = willEat ? snake : snake.slice(0, -1);
  if(bodyCheck.some(p=>p.x===nx && p.y===ny)){
    alive = false;
    stopLoop();
    draw();
    return;
  }
  snake.unshift({x:nx,y:ny});
  if(willEat){
    score++;
    updateScore();
    randFood();
  }else{
    snake.pop();
  }
  draw();
}

function setDir(d){
  const map = {up:{x:0,y:-1},down:{x:0,y:1},left:{x:-1,y:0},right:{x:1,y:0}};
  const nd = map[d];
  if(!nd) return;
  if(nd.x === -dir.x && nd.y === -dir.y) return;
  nextDir = nd;
}

function setFood(x,y){
  food = {x,y};
  draw();
}

function startLoop(){
  if(intervalId) return;
  intervalId = setInterval(tick, 140);
}
function stopLoop(){
  clearInterval(intervalId);
  intervalId = null;
}

document.getElementById('start').onclick = startLoop;
document.getElementById('pause').onclick = stopLoop;
document.getElementById('reset').onclick = ()=>{stopLoop(); reset();};

document.addEventListener('keydown', e=>{
  const k = e.key;
  if(k==='ArrowUp') setDir('up');
  else if(k==='ArrowDown') setDir('down');
  else if(k==='ArrowLeft') setDir('left');
  else if(k==='ArrowRight') setDir('right');
});

reset();

window.game = {
  w, h,
  reset,
  tick,
  setDir,
  setFood,
  snake: ()=>snake.map(p=>[p.x,p.y]),
  food: ()=>[food.x, food.y],
  alive: ()=>alive,
  score: ()=>score
};
</script>
</body>
</html>
